{
  "$schema": "https://opencode.ai/config.json"
}

{
  "name": "laya-drift",
  "private": true,
  "type": "module",
  "scripts": {
    "setup": "bash scripts/setup.sh",
    "typecheck": "tsc --noEmit",
    "daemon": ".venv/bin/python src/driftd.py",
    "smoke": ".venv/bin/python scripts/smoke.py",
    "eval": "bun scripts/eval.ts",
    "deepswe": "bun scripts/deepswe/run.ts",
    "deepswe:analyze": "bun scripts/deepswe/analyze.ts"
  },
  "devDependencies": {
    "@types/node": "22.13.9",
    "typescript": "5.8.2"
  }
}

{
  "name": "laya-drift-plugins",
  "private": true,
  "type": "module",
  "dependencies": {
    "@opencode-ai/plugin": "1.3.17",
    "@opentui/core": "0.5.11",
    "@opentui/solid": "0.5.11",
    "solid-js": "1.9.12"
  }
}
